/**
 * A trip's days (v2.7653, punch list #379, PR 1: the rules alone, no screen). A trip is one going-out to a
 * site and coming back: people, and for each person the days they were on it. Each day is one of three
 * kinds, Getting ready, On the road or At the site, and a person can be off a day in the middle (the day
 * is simply not in their days). Where a trip stands, Planned, Out now or Back, is read from its days and
 * today. Nobody types it.
 *
 * A trip is a reading laid over the clock. Nothing here writes, and nothing a trip holds changes a clock
 * row, a bill or a cost. Pure: days are `YYYY-MM-DD` strings in the company's calendar, compared as text.
 */

export type TripDayKind = 'ready' | 'road' | 'site'

/** The three kinds in the order a strip stacks them: the site first, since it is the figure asked for. */
export const TRIP_DAY_KINDS: ReadonlyArray<TripDayKind> = ['site', 'road', 'ready']

export const TRIP_DAY_LABEL: Readonly<Record<TripDayKind, string>> = {
  ready: 'Getting ready',
  road: 'On the road',
  site: 'At the site',
}

/** One person's days on a trip: the day, and its kind. A day off is a day that is not here. */
export type TripDays = Readonly<Record<string, TripDayKind>>

export type TripPerson = {
  /** How the clock's rows name the same person; the reads make it, the rules only compare it. */
  personKey: string
  name: string
  days: TripDays
}

export type Trip = {
  id: string
  people: ReadonlyArray<TripPerson>
  /** The jobs the trip's work goes on. Optional for good: a trip belongs to the site, never to a job. */
  jobIds?: ReadonlyArray<string>
}

export type TripStanding = 'planned' | 'out' | 'back'

export const TRIP_STANDING_LABEL: Readonly<Record<TripStanding, string>> = {
  planned: 'Planned',
  out: 'Out now',
  back: 'Back',
}

const YMD = /^\d{4}-\d{2}-\d{2}$/

export function isYmd(v: unknown): v is string {
  if (typeof v !== 'string' || !YMD.test(v)) return false
  const t = Date.parse(v + 'T12:00:00Z')
  return Number.isFinite(t) && new Date(t).toISOString().slice(0, 10) === v
}

export function isTripDayKind(v: unknown): v is TripDayKind {
  return v === 'ready' || v === 'road' || v === 'site'
}

/** A day `n` days after `ymd` (before it when `n` is negative). Noon UTC, so no clock change moves a day. */
export function addDays(ymd: string, n: number): string {
  const d = new Date(ymd + 'T12:00:00Z')
  d.setUTCDate(d.getUTCDate() + n)
  return d.toISOString().slice(0, 10)
}

/** Whole days from `a` to `b`: 0 for the same day, negative when `b` is before `a`. */
export function daysBetween(a: string, b: string): number {
  return Math.round((Date.parse(b + 'T12:00:00Z') - Date.parse(a + 'T12:00:00Z')) / 86_400_000)
}

/** Every day from `first` to `last`, both ends in; nothing when `last` is before `first`. */
export function daysInRange(first: string, last: string): string[] {
  const out: string[] = []
  for (let d = first; d <= last; d = addDays(d, 1)) out.push(d)
  return out
}

/** What is stored for a person's days, read back: anything that is not a real day with a real kind is dropped. */
export function parseTripDays(raw: unknown): TripDays {
  if (raw == null || typeof raw !== 'object' || Array.isArray(raw)) return {}
  const out: Record<string, TripDayKind> = {}
  for (const [ymd, kind] of Object.entries(raw as Record<string, unknown>)) if (isYmd(ymd) && isTripDayKind(kind)) out[ymd] = kind
  return out
}

/**
 * One tap on a day: At the site, On the road, Getting ready, then off, then round again. A day starts as
 * At the site, so the common trip needs no tap at all.
 */
export function nextDayKind(kind: TripDayKind | null): TripDayKind | null {
  return kind === 'site' ? 'road' : kind === 'road' ? 'ready' : kind === 'ready' ? null : 'site'
}

/** A run of days painted At the site: what picking a first and a last day gives before any tap. */
export function paintDays(first: string, last: string): TripDays {
  const out: Record<string, TripDayKind> = {}
  for (const d of daysInRange(first, last)) out[d] = 'site'
  return out
}

/** A person's days with one day tapped (to `kind`, or off when `kind` is null). */
export function withDay(days: TripDays, ymd: string, kind: TripDayKind | null): TripDays {
  const out: Record<string, TripDayKind> = { ...days }
  if (kind) out[ymd] = kind
  else delete out[ymd]
  return out
}

/**
 * A trip's kind on a day, over everyone on it: At the site when anyone was, else On the road, else
 * Getting ready, else nothing. This is the day a strip and a row draw, and the day *days at the site* counts.
 */
export function tripDayKind(trip: Trip, ymd: string): TripDayKind | null {
  let best: TripDayKind | null = null
  for (const p of trip.people) {
    const k = p.days[ymd]
    if (k === 'site') return 'site'
    if (k === 'road') best = 'road'
    else if (k === 'ready' && best == null) best = 'ready'
  }
  return best
}

/** A trip's first and last day over everyone on it; null for a trip with no day yet. */
export function tripSpan(trip: Trip): { first: string; last: string } | null {
  let first: string | null = null
  let last: string | null = null
  for (const p of trip.people)
    for (const ymd of Object.keys(p.days)) {
      if (first == null || ymd < first) first = ymd
      if (last == null || ymd > last) last = ymd
    }
  return first != null && last != null ? { first, last } : null
}

/** Every day from the trip's first to its last, with the trip's kind that day (null for a day nobody was on it). */
export function tripDayList(trip: Trip): Array<{ ymd: string; kind: TripDayKind | null }> {
  const span = tripSpan(trip)
  if (!span) return []
  return daysInRange(span.first, span.last).map((ymd) => ({ ymd, kind: tripDayKind(trip, ymd) }))
}

export type TripDayCounts = { site: number; road: number; ready: number; /** Days anyone was on the trip. */ days: number }

/** The trip's days by kind, each day counted once however many people were on it. */
export function tripDayCounts(trip: Trip): TripDayCounts {
  const out: TripDayCounts = { site: 0, road: 0, ready: 0, days: 0 }
  for (const d of tripDayList(trip)) {
    if (!d.kind) continue
    out[d.kind] += 1
    out.days += 1
  }
  return out
}

/** One person's days by kind. */
export function personDayCounts(days: TripDays): TripDayCounts {
  const out: TripDayCounts = { site: 0, road: 0, ready: 0, days: 0 }
  for (const kind of Object.values(days)) {
    out[kind] += 1
    out.days += 1
  }
  return out
}

/**
 * Where a trip stands, read from its days and today: Planned while its first day is ahead, Out now from
 * its first day through its last, Back after. A trip with no day yet is Planned.
 */
export function tripStanding(trip: Trip, todayYmd: string): TripStanding {
  const span = tripSpan(trip)
  if (!span || span.first > todayYmd) return 'planned'
  return span.last >= todayYmd ? 'out' : 'back'
}

/** Trips in the order they went out: by first day, then last day, then id; a trip with no day last. */
export function sortTrips<T extends Trip>(trips: ReadonlyArray<T>): T[] {
  const key = (t: T) => {
    const s = tripSpan(t)
    return s ? `${s.first}:${s.last}:${t.id}` : `9999-99-99::${t.id}`
  }
  return [...trips].sort((a, b) => key(a).localeCompare(key(b)))
}

/** The one thing a trip needs before it saves: one person with one day. */
export function tripCanSave(trip: Pick<Trip, 'people'>): boolean {
  return trip.people.some((p) => Object.keys(p.days).length > 0)
}

/**
 * The trip a person was on that day, and the day's kind for them; null when no trip covers that person
 * that day. Two trips that both claim the day is a mistake to fix on the screen: the one that went out
 * first holds it, so an hour is never counted twice.
 */
export function tripDayOfPerson<T extends Trip>(tripsInOrder: ReadonlyArray<T>, personKey: string, ymd: string): { trip: T; kind: TripDayKind } | null {
  for (const trip of tripsInOrder)
    for (const p of trip.people) {
      if (p.personKey !== personKey) continue
      const kind = p.days[ymd]
      if (kind) return { trip, kind }
    }
  return null
}

/** Person-days two trips both claim, for the screen to say so; empty when the trips keep apart. */
export function overlappingTripDays(trips: ReadonlyArray<Trip>): Array<{ personKey: string; ymd: string; tripIds: string[] }> {
  const held = new Map<string, string[]>()
  for (const trip of sortTrips(trips))
    for (const p of trip.people)
      for (const ymd of Object.keys(p.days)) {
        const key = `${p.personKey}\u0000${ymd}`
        const ids = held.get(key) ?? []
        if (!ids.includes(trip.id)) ids.push(trip.id)
        held.set(key, ids)
      }
  const out: Array<{ personKey: string; ymd: string; tripIds: string[] }> = []
  for (const [key, tripIds] of held) {
    if (tripIds.length < 2) continue
    const [personKey = '', ymd = ''] = key.split('\u0000')
    out.push({ personKey, ymd, tripIds })
  }
  return out.sort((a, b) => a.ymd.localeCompare(b.ymd) || a.personKey.localeCompare(b.personKey))
}
